				if (oldVNode._dom == oldDom) {
					oldVNode._parent = oldParentVNode;
					oldDom = null;
					if (oldVNode._parent) {
						let searchVNode = oldVNode._parent;
						let searchIndex =
							searchVNode._children.indexOf(oldVNode) + 1;
						for (
							;
							searchIndex < searchVNode._children.length &&
							oldDom == null;
							searchIndex++
						) {
							let sibling = searchVNode._children[searchIndex];
							oldDom =
								sibling != null && sibling._dom != null
									? sibling._nextDom || sibling._dom
									: null;
						}
						if (
							oldDom == null &&
							typeof searchVNode.type == 'function'
						) {
							oldDom = getDomSibling(searchVNode);
						}
					}
				}

				unmount(oldVNode, oldVNode, false);
				oldChildren[i] = null;
			}

			continue;
		}

